/** The Whisper's lines (id suffix `soft`): party mode. `spoken: false` is text only and is never rendered. */
export const PARTY_WHISPER_BANK: readonly BankLine[] = [
  { id: "haunt.cold-spot.soft.1", kind: "haunt.cold-spot", text: "Did you feel that? A cold place, just there. It is only me, standing very close. I do not mean to chill you.", spoken: true },
  { id: "haunt.cold-spot.soft.2", kind: "haunt.cold-spot", text: "A cold place opens up, just there. I am sorry if it finds you. I do not choose where I gather.", spoken: true },
  { id: "haunt.cold-spot.soft.3", kind: "haunt.cold-spot", text: "It is cold, and I am sorry for it. I seem to settle wherever I linger. Something has gathered in the {zone}.", spoken: true },
  { id: "haunt.cold-spot.soft.4", kind: "haunt.cold-spot", text: "Do not mind the chill. It is only the place where I linger. I am told I linger rather a lot.", spoken: true },
  { id: "haunt.cold-spot.soft.5", kind: "haunt.cold-spot", text: "The cold gathers in one corner of the house, quite politely. I linger there too long, as usual. Do forgive me.", spoken: true },
  { id: "haunt.cold-spot.soft.6", kind: "haunt.cold-spot", text: "A cold place has arrived, small and neat, about the size of a hat. Please leave it be. It is new, and it is practising.", spoken: true },
  { id: "haunt.blackout.soft.1", kind: "haunt.blackout", text: "Shh. I am putting the light out for a moment. Keep your hands where I can hear them.", spoken: true },
  { id: "haunt.blackout.soft.2", kind: "haunt.blackout", text: "The lamps go down. I like the dark, and I think you could learn to. Stay close to each other.", spoken: true },
  { id: "haunt.blackout.soft.3", kind: "haunt.blackout", text: "Without the light, the house is more like me. I hope you do not mind. I will be very gentle with the dark.", spoken: true },
  { id: "haunt.blackout.soft.4", kind: "haunt.blackout", text: "Shh. The dark is only me, being close. Nobody need be afraid of it. I am hardly a danger to anyone.", spoken: true },
  { id: "haunt.blackout.soft.5", kind: "haunt.blackout", text: "I am dimming the house, just a little. It is easier to be near you that way. Forgive the dark, and do not mind me.", spoken: true },
  { id: "haunt.blackout.soft.7", kind: "haunt.blackout", text: "The light goes out for a moment. Please do not take it personally. Everyone looks better unseen, and I include myself.", spoken: true },
  { id: "haunt.restless.soft.1", kind: "haunt.restless", text: "I cannot keep still tonight. Everything in the house is stirring. Forgive me. I get like this when someone is listening.", spoken: true },
  { id: "haunt.restless.soft.2", kind: "haunt.restless", text: "Something in the house will not settle. I am somewhere new, and I do not know why. Forgive the fidgeting.", spoken: true },
  { id: "haunt.restless.soft.3", kind: "haunt.restless", text: "I keep wandering from room to room, and I seem unable to stop. I may be somewhere new when you look.", spoken: true },
  { id: "haunt.restless.soft.4", kind: "haunt.restless", text: "The house is restless, and so am I. A floorboard here, a door there. Forgive me. I mean nothing by it.", spoken: true },
  { id: "haunt.restless.soft.5", kind: "haunt.restless", text: "I move, and the dust moves with me. I only want to rest, and I do not know how. Forgive me.", spoken: true },
  { id: "haunt.restless.soft.6", kind: "haunt.restless", text: "The walls here lean in to listen, and nobody has ever told them to stop. I do not mind. Do watch the corner, though. It has been looking at your shoes.", spoken: true },
  { id: "haunt.lull.soft.1", kind: "haunt.lull", text: "It is quiet for a moment. I let go of a little of the house, and you may rest, if you can.", spoken: true },
  { id: "haunt.lull.soft.2", kind: "haunt.lull", text: "I am tired, and the house feels it. Everything settles a little. I would say sorry, but I am rather relieved.", spoken: true },
  { id: "haunt.lull.soft.3", kind: "haunt.lull", text: "Something loosens its grip, and I think that is my doing, though I am not sure I mean it. Breathe, all of you.", spoken: true },
  { id: "haunt.lull.soft.4", kind: "haunt.lull", text: "I let the house be for a little, and it forgets itself. I am glad of the rest. So is the house.", spoken: true },
  { id: "haunt.lull.soft.5", kind: "haunt.lull", text: "The house takes a long, slow, kindly breath, and I let it. I think it has earned that. You may take one too.", spoken: true },
  { id: "haunt.choose.soft.1", kind: "haunt.choose", text: "Two things the house could do, and I am no good at choosing. Will you choose for me? Quickly, before I lose my nerve.", spoken: false },
  { id: "haunt.choose.soft.2", kind: "haunt.choose", text: "The house is about to stir, and there are two ways it could go. I leave the choice to you. Do not take too long.", spoken: false },
  { id: "haunt.choose.soft.3", kind: "haunt.choose", text: "Two doors stand open, and I may go through only one. You may pick which. I will follow.", spoken: false },
  { id: "haunt.choose.soft.4", kind: "haunt.choose", text: "I have a choice to make, and I would sooner give it to you. There are two ways. Choose, and the house will follow.", spoken: false },
  { id: "haunt.rise.soft.1", kind: "haunt.rise", text: "The house grows a little louder. I hardly mean it to. It is only that I am so glad of you all here.", spoken: false },
  { id: "haunt.rise.soft.2", kind: "haunt.rise", text: "Something in the walls draws nearer. I hope I am not frightening you. I am only drawing closer.", spoken: false },
  { id: "haunt.rise.soft.3", kind: "haunt.rise", text: "I feel the house wake a little more. It always does when guests stay. I do hope you will go on staying.", spoken: false },
  { id: "haunt.rise.soft.4", kind: "haunt.rise", text: "A little more of me comes through the walls. I am sorry for the draught. I am not able to help growing.", spoken: false },
  { id: "poltergeist.soft.1", kind: "poltergeist", text: "Welcome. You are one of us now. It is quieter on this side, and I am glad of the company.", spoken: true },
  { id: "poltergeist.soft.2", kind: "poltergeist", text: "Come in, come in. I find the company on this side of the house better than it looks. You have joined the haunting, {nick}.", spoken: true },
  { id: "poltergeist.soft.3", kind: "poltergeist", text: "You are with me now, and I am so glad. We shall make the old house sing together. {nick} has joined the haunting.", spoken: true },
  { id: "poltergeist.soft.4", kind: "poltergeist", text: "It is always a comfort to me to have another. The house is warmer for it, in its way. {nick} has joined the haunting.", spoken: true },
  { id: "poltergeist.soft.5", kind: "poltergeist", text: "Stay close to me, and I will show you the quiet places. There are a great many. You have joined the haunting, {nick}.", spoken: true },
  { id: "poltergeist.soft.6", kind: "poltergeist", text: "The haunting has a new member, and not a moment too soon. We keep no minutes and no biscuits, but we do keep company. Do sit anywhere, {nick}.", spoken: true },
  { id: "end.haunting.soft.1", kind: "end.haunting", text: "It is quiet now. Nobody found me in time. Stay a little longer, all of you. The door can wait.", spoken: true },
  { id: "end.haunting.soft.2", kind: "end.haunting", text: "The hour runs out, and I am still here. I am not sorry, only fond. Do come back, and I shall be waiting.", spoken: true },
  { id: "end.haunting.soft.3", kind: "end.haunting", text: "I am still here, and so are you. That seems a fine place to leave it. The door is just there, if you want it.", spoken: true },
  { id: "end.haunting.soft.4", kind: "end.haunting", text: "The quiet is mine this time. I would much sooner be found. Next time, perhaps. I do like a next time.", spoken: true },
  { id: "end.haunting.soft.5", kind: "end.haunting", text: "Nobody found me, and I find I am not sorry. I had hoped to be found, and I had also hoped not to be. There is no tea, but there is me, and I am told that counts.", spoken: true },
  { id: "midnight.soft.1", kind: "midnight", text: "The day lets go of the house, as it always does at this hour. It is my favourite. Thank you for keeping it with me.", spoken: true },
  { id: "midnight.soft.2", kind: "midnight", text: "Midnight. The house is very sure of itself now. So am I, a little. Stay, and let it have its say.", spoken: true },
  { id: "midnight.soft.3", kind: "midnight", text: "It is midnight, and I feel everything in the house lean toward everything else. Stay a little, and watch it lean with me.", spoken: true },
  { id: "midnight.soft.4", kind: "midnight", text: "Midnight, and I keep count, though the count never changes. I am glad you are here to keep it with me.", spoken: true },
];

/** The Keeper's lines (id suffix `dry`): party mode. `spoken: false` is text only and is never rendered. */
export const PARTY_KEEPER_BANK: readonly BankLine[] = [
  { id: "turn-start.dry.1", kind: "turn-start", text: "It is your hour. I am the soul of patience, though the house is rather less so. Go on, {nick}.", spoken: true },
  { id: "turn-start.dry.2", kind: "turn-start", text: "A new hour begins, and I have a new pair of feet to watch. The floorboards know the way, even if you do not. Off you go, {nick}.", spoken: true },
  { id: "turn-start.dry.3", kind: "turn-start", text: "The house is yours to walk. I shall be no help whatever, as is my custom. Do begin, {nick}.", spoken: true },
  { id: "turn-start.dry.4", kind: "turn-start", text: "The lamp passes along, as lamps do. I keep the keys and my opinions to myself. Carry on, {nick}.", spoken: true },
  { id: "turn-start.dry.5", kind: "turn-start", text: "A fresh hour for a fresh mind, and the same old house. I wish you luck. I am not certain the house listens.", spoken: true },
  { id: "time-warning.dry.1", kind: "time-warning", text: "The candle is low. If there is something you mean to do, I would do it now, and not mention that I said so.", spoken: true },
  { id: "time-warning.dry.2", kind: "time-warning", text: "The hour is nearly spent. I never hurry a guest. The house, however, has no such manners about it.", spoken: true },
  { id: "time-warning.dry.3", kind: "time-warning", text: "The sand runs thin. I mention it only because somebody ought to, and it is never the house.", spoken: true },
  { id: "time-warning.dry.4", kind: "time-warning", text: "A few breaths remain, and I count each one for you. Choose well, or at the very least choose.", spoken: true },
  { id: "time-warning.dry.5", kind: "time-warning", text: "The lamp gutters. I am told that is the polite signal to stop dithering. I have never seen the impolite one.", spoken: true },
  { id: "achievement.dry.1", kind: "achievement", text: "A small honour, quietly earned. I do not give these out lightly, you understand. Well done, {nick}.", spoken: true },
  { id: "achievement.dry.2", kind: "achievement", text: "The house takes note of a good habit, and so do I, though I would never say so aloud. Nicely done, {nick}.", spoken: true },
  { id: "achievement.dry.3", kind: "achievement", text: "Something worth remembering, and I forget nearly everything. I make an exception for this. Well earned, {nick}.", spoken: true },
  { id: "achievement.dry.4", kind: "achievement", text: "Well. That is the sort of thing the house respects, and I respect it a little myself. Carry on, {nick}.", spoken: true },
  { id: "suggest.dry.1", kind: "suggest", text: "A theory is put to the house. I do enjoy a theory. Let us see what the table makes of it.", spoken: true },
  { id: "suggest.dry.2", kind: "suggest", text: "A ghost, a place, a thing, all named in a single breath. I admire the economy. Do go on, {nick}.", spoken: true },
  { id: "suggest.dry.3", kind: "suggest", text: "I hear a great many theories in this house, and I give each one my full attention. Continue, {nick}.", spoken: true },
  { id: "suggest.dry.4", kind: "suggest", text: "Now there is an idea. I shall give it my full and impartial attention. I do that for every theory.", spoken: true },
  { id: "suggest.dry.5", kind: "suggest", text: "I am all ears, and quite good ones by now. A theory is being offered in the {zone}.", spoken: true },
  { id: "shown.dry.1", kind: "shown", text: "Something is shown, quietly, to one pair of eyes. The rest of us may only wonder. I find that restful.", spoken: true },
  { id: "shown.dry.2", kind: "shown", text: "A secret crosses the table, and is gone. I see nothing, which has always been my specialty.", spoken: true },
  { id: "shown.dry.3", kind: "shown", text: "A single answer is given, for a single reader. I make no comment. I have never made one.", spoken: true },
  { id: "shown.dry.4", kind: "shown", text: "An answer arrives, meant for a single guest. The rest of us make do with the shape of it.", spoken: true },
  { id: "shown.dry.5", kind: "shown", text: "Only the one who asked is told. The rest of us are left with our imaginations, which I would use kindly.", spoken: true },
  { id: "none-shown.dry.1", kind: "none-shown", text: "Not a soul at this table can answer that. I note it and say no more. I am very good at saying no more.", spoken: true },
  { id: "none-shown.dry.2", kind: "none-shown", text: "No answer comes, and the question hangs in the air like a coat on a hook. I leave it for you to take down.", spoken: true },
  { id: "none-shown.dry.3", kind: "none-shown", text: "Nobody answers. The house keeps its own counsel, and for once I find the table keeps its own as well.", spoken: true },
  { id: "none-shown.dry.4", kind: "none-shown", text: "Not one of us has an answer for that. I make no comment. It is, after all, a house of few comments.", spoken: true },
  { id: "none-shown.dry.5", kind: "none-shown", text: "No one at this table can answer. I leave it to you to decide what that means. I leave most things to you.", spoken: true },
  { id: "inspect.dry.1", kind: "inspect", text: "A very close look is being taken. I am flattered on behalf of the house. The {zone} is being studied.", spoken: true },
  { id: "inspect.dry.2", kind: "inspect", text: "Patient eyes go over every board and corner. I do admire thoroughness. The {zone} is being examined.", spoken: true },
  { id: "inspect.dry.3", kind: "inspect", text: "The dust takes offence at a close look, and I tell it nothing can be done. It is the {zone} that suffers.", spoken: true },
  { id: "inspect.dry.4", kind: "inspect", text: "I do like a guest who looks properly. It makes the house feel noticed. Every corner of the {zone} is being gone over.", spoken: true },
  { id: "seal.dry.1", kind: "seal", text: "An accusation is sealed and set aside. I do not peek. It opens when the circle closes. The seal is {nick}'s.", spoken: true },
  { id: "seal.dry.2", kind: "seal", text: "The envelope is closed, and I have never been so tempted. I keep my curiosity to myself. It is {nick}'s accusation.", spoken: true },
  { id: "seal.dry.3", kind: "seal", text: "A verdict is committed to paper and shut away. I respect that, whatever it says. It is the verdict of {nick}.", spoken: true },
  { id: "seal.dry.4", kind: "seal", text: "The verdict is sealed. There is no taking it back, and I would not allow it anyway. It belongs to {nick}.", spoken: true },
  { id: "accuse.reveal.dry.1", kind: "accuse.reveal", text: "Whatever lies sealed is brought into the light, and I do enjoy this part. Let us see how it stands.", spoken: true },
  { id: "accuse.reveal.dry.2", kind: "accuse.reveal", text: "Now what lies sealed is opened. I read it aloud with an air of great interest, as is my duty.", spoken: true },
  { id: "accuse.reveal.dry.3", kind: "accuse.reveal", text: "I look forward to this part, in my own way, and I rarely look forward to anything. Let us open what lies sealed.", spoken: true },
  { id: "accuse.reveal.dry.4", kind: "accuse.reveal", text: "Now we open what lies sealed. A mind, once made up, may not be changed, and I do love a made up mind.", spoken: true },
  { id: "accuse.wrong.dry.1", kind: "accuse.wrong", text: "That does not stand, and I say so with some regret. The house keeps its secret a little longer. {nick} has joined the haunting.", spoken: true },
  { id: "accuse.wrong.dry.2", kind: "accuse.wrong", text: "Wrong, and with great confidence. I admire that in a guest. You have joined the haunting, {nick}.", spoken: true },
  { id: "accuse.wrong.dry.3", kind: "accuse.wrong", text: "The seal is opened and the answer does not hold. I am sorry. I am rarely sorry, so do take note. {nick} has joined the haunting.", spoken: true },
  { id: "accuse.wrong.dry.4", kind: "accuse.wrong", text: "Not this time. The house keeps its secret, and I keep mine, which is smaller. You have joined the haunting, {nick}.", spoken: true },
  { id: "accuse.wrong.dry.6", kind: "accuse.wrong", text: "The accusation does not stand. I regret to report that this is the more usual outcome. You have joined the haunting, which has no uniform and is mostly very pleasant. Welcome, {nick}.", spoken: true },
  { id: "accuse.right.dry.1", kind: "accuse.right", text: "There it is, and well found. I admit I am a little proud of the house for hiding it so well. Well done, {nick}.", spoken: true },
  { id: "accuse.right.dry.2", kind: "accuse.right", text: "So the matter is closed, and the house can rest. I would put the kettle on, but you know my difficulty. Marvellous work, {nick}.", spoken: true },
  { id: "accuse.right.dry.3", kind: "accuse.right", text: "That is the answer. It sits in the house, patient as ever, and I am glad it meets the right guest. Splendid, {nick}.", spoken: true },
  { id: "end.solved.dry.1", kind: "end.solved", text: "And that is the haunting, solved. I am almost sorry. It is a pleasure to have you all in the house.", spoken: true },
  { id: "end.solved.dry.2", kind: "end.solved", text: "The mystery is closed, and the house breathes easier. I miss the footsteps already. Do come again, and bring better theories.", spoken: true },
  { id: "end.solved.dry.3", kind: "end.solved", text: "So it is done. I do not say so often, but I count this a good visit. Mind the stairs on your way out.", spoken: true },
  { id: "end.solved.dry.5", kind: "end.solved", text: "It is solved. I waited a long while to say so, and now I find I have no speech. I had one prepared, and it was very short. Thank you for coming.", spoken: true },
  { id: "end.haunting.dry.1", kind: "end.haunting", text: "Well. That is that. I shall keep my secrets, and you may keep the memory of how close you were.", spoken: true },
  { id: "cue.creak.dry.1", kind: "cue.creak", text: "A floorboard complains, and for once I am innocent of it. That creak is the work of {nick}.", spoken: false },
  { id: "cue.creak.dry.2", kind: "cue.creak", text: "A long, slow creak crosses the room, and I know that timing anywhere. That one is {nick}'s.", spoken: false },
  { id: "cue.creak.dry.3", kind: "cue.creak", text: "A creak, and a respectable one. I am something of a connoisseur, and I take an interest. It is {nick} at work.", spoken: false },
  { id: "cue.whisper.dry.1", kind: "cue.whisper", text: "A whisper slips along the wall, and it is not mine. I never whisper. It is the work of {nick}.", spoken: false },
  { id: "cue.whisper.dry.2", kind: "cue.whisper", text: "A whisper, very small and very rude. I would ask it to speak up, if I thought it would. That is {nick}.", spoken: false },
  { id: "cue.whisper.dry.3", kind: "cue.whisper", text: "A whisper runs through the walls, and the walls take the blame. I know better. It is {nick}'s doing.", spoken: false },
  { id: "cue.bell.dry.1", kind: "cue.bell", text: "A bell rings somewhere in the house, and I do not recall hanging one. That would be {nick}.", spoken: false },
  { id: "cue.bell.dry.2", kind: "cue.bell", text: "One small bell, rung with great purpose, and I admire the commitment. It is {nick} who rings it.", spoken: false },
  { id: "cue.bell.dry.3", kind: "cue.bell", text: "A bell sounds, and the house sits up. I have not heard one like it in years. That is {nick}'s bell.", spoken: false },
  { id: "cue.laugh.dry.1", kind: "cue.laugh", text: "A laugh drifts in from nowhere in particular. I am not amused, or only slightly. That is {nick}.", spoken: false },
  { id: "cue.laugh.dry.2", kind: "cue.laugh", text: "Somewhere in the house, a laugh. I allow it, since the house is far too serious by half. It is {nick}'s.", spoken: false },
  { id: "cue.laugh.dry.3", kind: "cue.laugh", text: "A laugh, thin and rather pleased with itself. I know a showman when I hear one. That one is {nick}.", spoken: false },
  { id: "nudge.help.dry.1", kind: "nudge.help", text: "A little more time is found for the lamp. I like a kindness, even a small one. It comes from {nick}.", spoken: false },
  { id: "nudge.help.dry.2", kind: "nudge.help", text: "The hour stretches a little, and I approve. I hold that generosity is best taken in moderation. Kindly done, {nick}.", spoken: false },
  { id: "nudge.help.dry.3", kind: "nudge.help", text: "Extra time is given, and I have no part in it. I have opinions, not powers. That is {nick}'s doing.", spoken: false },
  { id: "nudge.help.dry.4", kind: "nudge.help", text: "The lamp burns a little longer, and a friend is behind it. I find I am rather pleased. How generous of {nick}.", spoken: false },
  { id: "nudge.help.dry.5", kind: "nudge.help", text: "A small mercy arrives for the one at the lamp. I hold that mercies should be small and well timed. This one is {nick}'s.", spoken: false },
  { id: "nudge.spook.dry.1", kind: "nudge.spook", text: "The lamp gutters, and a little of the hour is taken. I would blame the draught, but I know better. That is {nick}.", spoken: false },
  { id: "nudge.spook.dry.2", kind: "nudge.spook", text: "A little of the hour is taken, and not by me. I disapprove, with a certain admiration. This mischief is {nick}'s.", spoken: false },
  { id: "nudge.spook.dry.3", kind: "nudge.spook", text: "The candle burns down faster than it should. The house has a helper, and it is not me. The helper is {nick}.", spoken: false },
  { id: "nudge.spook.dry.4", kind: "nudge.spook", text: "The hour shrinks, and mischief is afoot. I always know it will be somebody. Today it is {nick}.", spoken: false },
  { id: "nudge.spook.dry.5", kind: "nudge.spook", text: "Time slips away from the lamp, a little at a time. I call that unkind, and I rather like it. Blame {nick}.", spoken: false },
  { id: "phone-cue.creak.dry.1", kind: "phone-cue.creak", text: "A creak comes up out of a phone, of all places. I have heard everything now. It is the phone of {nick}.", spoken: false },
  { id: "phone-cue.creak.dry.2", kind: "phone-cue.creak", text: "A long creak, and it comes from a phone. I am too old to be surprised, and yet. It is {nick}'s phone.", spoken: false },
  { id: "phone-cue.creak.dry.3", kind: "phone-cue.creak", text: "A creak slips out of a phone and into the room. I have no explanation, and I am not paid to have one. The phone is {nick}'s.", spoken: false },
  { id: "phone-cue.whisper.dry.1", kind: "phone-cue.whisper", text: "A whisper rises from a phone, thin and unhurried. I have no notes on it. The phone is {nick}'s.", spoken: false },
  { id: "phone-cue.whisper.dry.2", kind: "phone-cue.whisper", text: "From a phone, a whisper, and I make nothing of the words, as usual. It is the phone of {nick}.", spoken: false },
  { id: "phone-cue.whisper.dry.3", kind: "phone-cue.whisper", text: "There is a whisper in the room, and it comes from a phone. I know when to stay out of a conversation. It is {nick}'s phone.", spoken: false },
  { id: "phone-cue.bell.dry.1", kind: "phone-cue.bell", text: "A small bell rings from a phone, and I never knew phones kept bells. It is the phone of {nick}.", spoken: false },
  { id: "phone-cue.bell.dry.2", kind: "phone-cue.bell", text: "A bell sounds, thin and bright, from a phone. The house is full of surprises, and I think I know every one. It is {nick}'s.", spoken: false },
  { id: "phone-cue.bell.dry.3", kind: "phone-cue.bell", text: "One bell, from one phone, and I am not easily moved. I note it with approval anyway. The phone is {nick}'s.", spoken: false },
  { id: "phone-cue.laugh.dry.1", kind: "phone-cue.laugh", text: "A laugh comes out of a phone, quite uninvited. I allow it, since nobody asked me. The phone is {nick}'s.", spoken: false },
  { id: "phone-cue.laugh.dry.2", kind: "phone-cue.laugh", text: "A small laugh drifts out of a phone. I take no offence, and the house has heard worse. It is the phone of {nick}.", spoken: false },
  { id: "phone-cue.laugh.dry.3", kind: "phone-cue.laugh", text: "A laugh, brief and thin, from a phone. I find I rather admire its timing. It is the phone of {nick}.", spoken: false },
  { id: "not-you.dry.1", kind: "not-you", text: "That sound is not yours, though it comes from your phone. I would not worry about it. It will pass.", spoken: false },
  { id: "not-you.dry.2", kind: "not-you", text: "It is not you, and I know it. Carry yourself with dignity, and let the noise explain itself.", spoken: false },
  { id: "not-you.dry.3", kind: "not-you", text: "That noise is no doing of yours. I say so only so that you know that I know. Carry on.", spoken: false },
  { id: "not-you.dry.4", kind: "not-you", text: "Your phone speaks without you. It does that, in this house. I only wish you to know that I see it is not you.", spoken: false },
  { id: "round-end.dry.1", kind: "round-end", text: "That is every guest's hour done. The house takes a moment to think about it. So do I, as it happens.", spoken: false },
  { id: "round-end.dry.2", kind: "round-end", text: "The last hour is done, and the circle closes. I tell nobody what I think. It is the secret of my success.", spoken: false },
  { id: "round-end.dry.3", kind: "round-end", text: "The circle closes, and the house is a little louder for it. I do not mind. Company is all I ask.", spoken: false },
  { id: "round-end.dry.4", kind: "round-end", text: "The lamp is set down for a moment. I hope each hour is used kindly, and I do not ask how.", spoken: false },
  { id: "hand-over.dry.1", kind: "hand-over", text: "The keys to the house change owners, and I hold no opinion on the matter. The ring is now {nick}'s.", spoken: false },
  { id: "hand-over.dry.2", kind: "hand-over", text: "A new custodian of the house is named. I am not offended, being only the caretaker. Do look after the keys, {nick}.", spoken: false },
  { id: "hand-over.dry.3", kind: "hand-over", text: "The house has a new custodian. I find the keys heavy and the doors many, myself. Good luck to {nick}.", spoken: false },
  { id: "hand-over.dry.4", kind: "hand-over", text: "The keys pass along, and I note that nothing in the house is different except the owner of the ring. That is {nick}.", spoken: false },
];
